//! The generators: schema data in, source files out.
//!
//! Each generator emits a whole file, including the `DO NOT EDIT` header naming
//! the regeneration command. Output is COMMITTED and checked by a test rather
//! than produced by a `build.rs`.
//!
//! A generated `.rs` file is subject to `cargo fmt --all -- --check`, so every
//! emitter here must produce output that is already a fixed point of rustfmt.
//! That is an acceptance property, not a nicety: if it drifts, the format gate
//! and the golden gate fight each other.

pub mod adapter_rs;
pub mod decl_rs;
pub mod handler_rs;
pub mod harness_req_rs;
pub mod wire_rs;

use crate::schema::Effect;

/// One file this crate owns end to end.
#[derive(Clone, Debug)]
pub struct GeneratedFile {
    /// Path relative to the workspace root.
    pub path: String,
    /// The complete file contents.
    pub contents: String,
}

/// Escape a string for emission as a Rust string literal.
///
/// Deliberately minimal: the effect contract's text is Haskell source and
/// English prose, so only quotes, backslashes and newlines occur. Anything else
/// passes through verbatim, which keeps non-ASCII (the em-dashes in the helper
/// docs) as itself rather than as an escape — matching how the hand-written
/// registry spells it.
#[must_use]
pub fn rust_string_literal(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The header every generated file carries, as a line comment using `prefix`.
///
/// One line: regeneration procedure, verification, and the decision to commit
/// output rather than build.rs it all live in this module's own doc comment
/// — not restated per file.
#[must_use]
pub fn header(prefix: &str, what: &str) -> String {
    format!(
        "{prefix}{what} — GENERATED by tidepool-protocol, DO NOT EDIT. Regenerate: \
         `cargo run -p tidepool-protocol --bin tidepool-protocol-gen` (see \
         tidepool-protocol/src/gen/mod.rs).\n"
    )
}

/// Every file generated for `effects`, in a stable order.
///
/// `decl_rs` runs unconditionally for every effect — it is pure Haskell decl
/// data, needed regardless of whether a real handler exists. `handler_rs`/
/// `wire_rs`/`adapter_rs` are gated on [`Effect::dispatched`] first: they emit
/// dispatch glue for a real `tidepool-handlers::EffectHandler`, which a
/// suspending effect (`dispatched: false` — `AskUser`/`ReadState` today) does
/// not have, so generating them would reference a handler struct that will
/// never exist. Among DISPATCHED effects, the wire and adapter files are
/// further emitted only for one that actually has something to put in them —
/// a `type_defs` vocabulary, and a `DomainMap` on at least one entry. That is
/// not a special case for one effect: Exec and Journal have empty
/// `type_defs`, so they get no wire module and no adapter module, and an
/// empty generated file would be worse than none.
#[must_use]
pub fn all_files(effects: &[Effect]) -> Vec<GeneratedFile> {
    let mut out = Vec::new();
    for e in effects {
        out.push(decl_rs::file(e));
        if e.dispatched {
            out.push(handler_rs::file(e));
            if wire_rs::has_wire_types(e) {
                out.push(wire_rs::file(e));
            }
            if adapter_rs::has_adapters(e) {
                out.push(adapter_rs::file(e));
            }
        }
    }
    out.push(decl_rs::module_index(effects));
    let dispatched: Vec<Effect> = effects.iter().filter(|e| e.dispatched).cloned().collect();
    out.push(handler_rs::module_index(&dispatched));
    if dispatched.iter().any(wire_rs::has_wire_types) {
        out.push(wire_rs::module_index(&dispatched));
    }
    out
}

/// snake_case of an UpperCamelCase name (`WorktreeId` -> `worktree_id`).
///
/// The one conversion for every generated Rust identifier that must not
/// cross a wire boundary: effect module names, generated type/parameter
/// names, and dispatch-arm binders all share this rule.
#[must_use]
pub fn snake_case(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_uppercase() {
            if i != 0 {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// The snake_case module name an effect's generated files live under.
#[must_use]
pub fn module_name(e: &Effect) -> String {
    snake_case(e.name)
}

/// Render one `    Ctor(field, …),` enum-variant line, wrapping onto its own
/// block the way rustfmt does once it would. Shared by [`handler_rs`] (the
/// dispatchable `<Eff>Req` enums) and [`harness_req_rs`] (the decode-only
/// suspension request enums) — both emit the identical "one variant per GADT
/// constructor" enum shape, just into different crates for different
/// purposes, so the rendering is the one shared piece.
///
/// The wrap condition is `fields.join(", ").chars().count() > 60` — NOT the
/// naive "does the whole `    Ctor(...),` line exceed the 100-column
/// `max_width`". rustfmt treats a tuple-variant's parenthesized field list as
/// CALL-LIKE syntax, governed by the separate `fn_call_width` heuristic
/// (`use_small_heuristics = Default`'s 60, i.e. 60% of `max_width`), applied
/// to the field list ALONE — the constructor name and indent are irrelevant
/// to the decision. Empirically probed against a real `rustfmt` invocation
/// (60 chars of joined fields stays single-line, 61 wraps) rather than
/// guessed: this crate's generated output must already be a fixed point of
/// `cargo fmt`, and a wrong threshold here is exactly the kind of
/// generator/format-gate fight that guarantee exists to prevent.
#[must_use]
pub fn render_variant(ctor: &str, fields: &[String]) -> String {
    if fields.is_empty() {
        return format!("    {ctor},\n");
    }
    let joined = fields.join(", ");
    if joined.chars().count() <= 60 {
        format!("    {ctor}({joined}),\n")
    } else {
        let mut out = format!("    {ctor}(\n");
        for f in fields {
            out.push_str(&format!("        {f},\n"));
        }
        out.push_str("    ),\n");
        out
    }
}

/// The shared `mod`-index body for a directory of generated effect modules.
///
/// `flatten` adds a re-export glob per module. The decl side wants it (the
/// crate root does `pub use generated::*`, so `tidepool_mcp::exec_decl` keeps
/// its path); the handler side does not (each effect's own module re-exports
/// its types, so a second glob here would just be an unused import).
fn index_body(prefix_what: &str, modules: &[String], flatten: bool) -> String {
    let mut out = header("//! ", prefix_what);
    out.push('\n');
    let mut names: Vec<String> = modules.to_vec();
    names.sort();
    for n in &names {
        out.push_str(&format!("pub mod {n};\n"));
    }
    if flatten {
        out.push('\n');
        for n in &names {
            out.push_str(&format!("pub use {n}::*;\n"));
        }
    }
    out
}
